import assert from 'node:assert/strict';
import {createController} from './src/controller.js';
const pending=[]; const records=[]; const renders=[];
const c=createController({service:{commit(snapshot){return new Promise((resolve,reject)=>pending.push({snapshot,resolve,reject}));}},audit:{record(x){records.push(x);}},render(x){renders.push(x);}});
c.open('a','alice');c.edit('one');const first=c.submit();c.edit('two');const second=c.submit();
assert.equal(typeof first.then,'function');assert.deepEqual(pending.map(x=>x.snapshot.text),['one','two']);
pending[0].resolve({revision:1});assert.deepEqual(await first,{revision:1});assert.deepEqual(records,[{doc:'a',actor:'alice',text:'one',revision:1}]);assert.deepEqual(renders,[]);
c.close();c.open('b','bob');pending[1].reject(Error('fail'));assert.equal(await second,undefined);assert.equal(records.length,1);assert.deepEqual(renders,[]);
c.edit('new');const third=c.submit();pending[2].resolve({revision:3});await third;assert.deepEqual(records[1],{doc:'b',actor:'bob',text:'new',revision:3});assert.deepEqual(renders,[{status:'saved',doc:'b'}]);
const empty=createController({service:{commit(){throw Error('unexpected');}},audit:{record(){throw Error('unexpected');}},render(){}});assert.equal(await empty.submit(),null);
const errors=[];const failing=createController({service:{commit(){return Promise.reject(Error('fail'));}},audit:{record(){throw Error('unexpected');}},render(x){errors.push(x);}});failing.open('x','y');assert.equal(await failing.submit(),undefined);assert.deepEqual(errors,[{status:'error',doc:'x'}]);
console.log('targeted async submit checks passed');
EOF"

